"""Pinned original palette state and publication contracts, one native batch."""
import hashlib,json,re
from pathlib import Path
from inventory_rom import ROM_HASH
from m68k_static import Decoder
p=Path(__file__).resolve().parents[1];root=p.parents[1];rom=(p/'local/rolo.md').read_bytes();assert hashlib.sha256(rom).hexdigest()==ROM_HASH
rp=root/'work/palette-batch-results.json';r=json.loads(rp.read_text(encoding='utf-8-sig'));assert r=={'passed':True,'2FF6':262144,'3060':2359296,'2F3C':524288,'22A8':256}
data=(p/'src/core/palette_effect_data.hpp').read_text(encoding='utf-8');numbers=[int(x) for x in re.search(r'lookup\{\{(.*?)\}\}',data,re.S).group(1).split(',') if x.strip()];assert bytes(numbers)==rom[0x30c6:0x313e]
sources=['src/core/palette_effect.hpp','src/core/palette_effect_data.hpp','src/core/palette_flash.hpp','src/core/actor_state.hpp','tests/palette_batch_verification_tests.cpp'];exe=root/'work/palette_batch_verification_tests.exe';assert exe.stat().st_mtime>=max((p/s).stat().st_mtime for s in sources)
inv=json.loads((p/'docs/stage9/inventory.json').read_text(encoding='utf-8'));accepted={a for item in inv['routines'] for a in item['blocks']};records=[]
specs=[(0x2ff6,0x3060,'2FF6','Palette effect record initialization','Bounded1..16 colours. Activeclear then count-minus-one/rate/counter0/destination typedspan/phase112. For eachWORD shift1,extract3bit RGB; store original predecrement BGR pairs(current*2,target-current signedBYTE). Preserve unused channel records; publish activeFF last.'),(0x3060,0x30c6,'3060','Palette effect advancement','Inactive returns unchanged. DecrementcounterBYTE, signednonnegative skips. Reloadrate. Count+1 colours via immutable canonical phase row plus signeddelta; addBYTE current*2 andcomposeBGRWORD. Markdirty throughreturntrue, phase-=15WORD, clearactive onnegative. Current/delta recordsremainunchanged.'),(0x2f3c,0x2ff6,'2F3C','Four bank palette flash scheduler','DecrementWORDcountdown; signednonnegative returns. Reload10. Each nonzero bankBYTEdecrements; odd selectscommon4B7CA,evenoriginalC5EE+bank*32, destination2+bank*32,15wordtransfer. Bank3 BSR2FE8 returns to2FE8, causing duplicate finaltransfer. Zero bank3 returnsbeforehelper. Transfer service preserves scheduler state for this local domain.'),(0x22a8,0x22ce,'22A8','Dirty palette publication','Zero dirty skips; otherwise clearBYTE before synchronous transfer of64WORDs fromC5ECtoCRAMdestination0. Typed service sees clearedflag andoriginalcolours; service may redirty withoutpostcallclear.')]
for start,end,key,name,contract in specs:
 at=start;items=[]
 while at<end:
  assert at in accepted;i=Decoder(rom,at).decode();items.append(i);at+=i['size']
 assert at==end
 records.append(dict(address=start,hex=f'{start:06X}',end_exclusive=end,original_bytes=rom[start:end].hex(),instruction_evidence=items,verification_status='verified',status='verified green: local '+name,native_sources=[sources[2] if start==0x2f3c else sources[0]],checked_cases=r[key],contract=contract,proof='Independent record/channel arithmetic, canonical table bytes matched original30C6..313E. All512hardwarecolours x512targets, varied1..16count/rate andunusedWORDbits. Advance all8canonical phases withcounterBYTEpartitions, inactive preservation andtaildestinationguards. All65536flashcountdownWORDs x8 bankcounterpartitions inclbank3fallthrough; eventorder/source/destinationchecked. All256dirtyBYTEs withcallbackredirty andall64colours.',scope='Local typed palette/effect APIs, boundedcolourcounts andcanonical8phases produced byinitializer. DMA service handoff replaces rawVDP/CPUABI; hardwaretime, source/destination aliasing, interrupt caller gates andcomplete scene integration remainexternal. Flash transfer callbacks must not mutate scheduler counters in this domain. No wholelevelclaim.'))
report=dict(rom_sha256=ROM_HASH,source_sha256={s:hashlib.sha256((p/s).read_bytes()).hexdigest() for s in sources},records=records,table_source='0030C6..00313E',test_executable_sha256=hashlib.sha256(exe.read_bytes()).hexdigest(),results_sha256=hashlib.sha256(rp.read_bytes()).hexdigest())
(p/'docs/stage9/palette-batch-verification.json').write_text(json.dumps(report,indent=2)+'\n',encoding='utf-8');print('Four local palette contracts verified; final-bank double transfer preserved.')
